package com.collegeerp.erp.email.controller;import com.collegeerp.erp.auth.security.CustomUserDetails;import com.collegeerp.erp.common.api.ApiResponse;import com.collegeerp.erp.email.dto.*;import com.collegeerp.erp.email.service.AccountTokenService;import com.collegeerp.erp.user.repository.UserRepository;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AccountEmailController{private final AccountTokenService tokens;private final UserRepository users;public AccountEmailController(AccountTokenService t,UserRepository u){tokens=t;users=u;}@PostMapping("/password/forgot")public ApiResponse<Void> forgot(@Valid @RequestBody ForgotPasswordRequest r){tokens.forgot(r.email());return ApiResponse.success("If an account exists for that email, a password reset link will be sent.",null);}@PostMapping("/password/reset")public ApiResponse<Void> reset(@Valid @RequestBody ResetPasswordRequest r){tokens.reset(r.token(),r.newPassword());return ApiResponse.success("Password reset successfully",null);}@PostMapping("/email-verification/request")public ApiResponse<Void> request(@AuthenticationPrincipal CustomUserDetails d){tokens.requestVerification(users.findById(d.getId()).orElseThrow());return ApiResponse.success("Verification email queued",null);}@PostMapping("/email-verification/confirm")public ApiResponse<Void> confirm(@Valid @RequestBody TokenRequest r){tokens.verify(r.token());return ApiResponse.success("Email verified successfully",null);}}
